### ① Concept Explanation

When multiple agents produce conflicting outputs — different answers, contradictory recommendations, or incompatible decisions — the system needs a **conflict resolution mechanism**. Conflicts arise from: different knowledge (agents trained on different data), different reasoning paths (non-determinism), or genuinely ambiguous problems. Resolution strategies include: **majority voting** (most common answer wins), **confidence-weighted voting** (agents with higher confidence scores dominate), **hierarchical authority** (senior agent overrides), **debate** (agents argue their positions to a judge), and **human escalation** (humans break ties). The choice depends on the stakes: low-stakes decisions → majority vote; high-stakes → debate + human confirmation.

### ② Implementation

```python
from collections import Counter
from pydantic import BaseModel
import statistics

class AgentAnswer(BaseModel):
    agent_name: str
    answer: str
    confidence: float  # 0.0 to 1.0
    reasoning: str

class ConflictResolver:
    """Multiple strategies for resolving conflicting agent outputs."""

    def majority_vote(self, answers: list[AgentAnswer]) -> AgentAnswer:
        """Most common answer wins."""
        answer_counts = Counter(a.answer for a in answers)
        winning_answer = answer_counts.most_common(1)[0][0]
        return next(a for a in answers if a.answer == winning_answer)

    def confidence_weighted_vote(self, answers: list[AgentAnswer]) -> AgentAnswer:
        """Weight votes by agent confidence scores."""
        answer_scores: dict[str, float] = {}
        for answer in answers:
            answer_scores[answer.answer] = (
                answer_scores.get(answer.answer, 0.0) + answer.confidence
            )
        winning_answer = max(answer_scores, key=answer_scores.get)
        logger.info(f"Confidence-weighted vote: {answer_scores}")
        return next(a for a in answers if a.answer == winning_answer)

    def debate_and_judge(
        self,
        answers: list[AgentAnswer],
        judge_llm,
        original_question: str,
    ) -> AgentAnswer:
        """LLM judge evaluates all answers and picks the best."""
        debate_prompt = f"""
Question: {original_question}

Multiple agents provided these answers:
{chr(10).join(f'{a.agent_name} (confidence={a.confidence:.0%}): {a.answer}\nReasoning: {a.reasoning}' for a in answers)}

As a judge, evaluate each answer's correctness, reasoning quality, and completeness.
Select the BEST answer and explain why.
Return: {{"selected_agent": "<name>", "justification": "<reason>"}}
"""
        response = judge_llm.invoke([{"role": "user", "content": debate_prompt}])
        try:
            import json
            selection = json.loads(response.content)
            selected_name = selection["selected_agent"]
            return next(a for a in answers if a.agent_name == selected_name)
        except Exception:
            # Fallback to confidence weighting
            return self.confidence_weighted_vote(answers)

    def resolve(
        self,
        answers: list[AgentAnswer],
        strategy: str = "confidence_weighted",
        **kwargs,
    ) -> tuple[AgentAnswer, bool]:
        """
        Resolve conflict between agents.
        Returns: (winning_answer, was_conflict)
        """
        unique_answers = len(set(a.answer for a in answers))
        if unique_answers == 1:
            return answers[0], False  # No conflict

        logger.warning(f"Conflict detected: {unique_answers} different answers from {len(answers)} agents")

        if strategy == "majority":
            return self.majority_vote(answers), True
        elif strategy == "confidence_weighted":
            return self.confidence_weighted_vote(answers), True
        elif strategy == "debate":
            return self.debate_and_judge(answers, **kwargs), True
        else:
            raise ValueError(f"Unknown conflict resolution strategy: {strategy}")
```
